import pytz
import json
import re

from datetime import datetime
from taf.analyzer.base.log_entry import LogEntry


class PdmlLogEntry(LogEntry):
    """
    Provides methods to parse, represent PDML log entry object in readable format.

    Methods:

    - :meth:`packet`: Provide packet of a PdmlLogEntry

    - :meth:`parse`: Provide PdmlLogEntry object

    Attributes:

    - :attr:`timezone`: timezone offset
    - :attr:`packet`: PDML packet

    """

    def __init__(self, packet, **kwargs):
        """
        Create PdmlLogEntry for a packet.

        :param Packet packet: pdml packet as input
        """
        super(PdmlLogEntry, self).__init__(**kwargs)
        self.__packet = packet

    def __str__(self):
        """
        Provides string representation of a PdmlLogEntry

        :return: String representation of PdmlLogEntry
        :rtype: str
        """
        result = json.dumps(
            {'timestamp': str(self.timestamp),
             'packet': ""},
            indent=2)
        result = re.sub(r'""', '"""%s"""' % str(self.__packet), result)
        return result

    @property
    def packet(self):
        """
        Provide Packet of PdmlLogEntry

        :return: Pdml packet
        :rtype: Packet
        """
        return self.__packet

    @classmethod
    def parse(cls, timezone, packet):
        """
        Provide PdmlLogEntry object
        :param str timezone: timezone offset
        :param Packet packet: pdml packet
        :return: PdmlLogEntry object
        """
        aware_timestamp = pytz.timezone(timezone).localize(datetime.utcfromtimestamp(
            float(packet["frame.time_epoch"].show)
        ))
        return PdmlLogEntry(
            packet=packet,
            timestamp=aware_timestamp
        )
